package com.wartec.wartecmod.port;

import com.wartec.wartecmod.port.planning.*;
import java.util.*;
import net.minecraft.nbt.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class CommandReliabilityTest {
    @Test public void acknowledgmentSurvivesUnchangedProblemBeyondTenSeconds(){CommandCenterState s=new CommandCenterState();s.notify("step","operation","unit",10,"power","Plan");s.acknowledge("step");s.notify("step","operation","unit",10000,"power","Plan");assertTrue(s.alerts.get("step").getBoolean("Acknowledged"));assertEquals(10,s.alerts.get("step").getLong("Tick"));}
    @Test public void changedReasonReopensNoticeImmediately(){CommandCenterState s=new CommandCenterState();s.notify("step","operation","unit",10,"power","Plan");s.acknowledge("step");s.notify("step","operation","unit",11,"unloaded","Plan");assertFalse(s.alerts.get("step").getBoolean("Acknowledged"));assertEquals("unloaded",s.alerts.get("step").getString("Reason"));}
    @Test public void recurrenceAfterRecoveryIsNewOccurrence(){CommandCenterState s=new CommandCenterState();s.notify("unit","empty","x",10);s.acknowledge("unit");s.resolveNotice("unit",20);s.notify("unit","empty","x",30);assertFalse(s.alerts.get("unit").getBoolean("Acknowledged"));assertFalse(s.alerts.get("unit").getBoolean("Resolved"));}
    @Test public void combatNoticesDoNotInvalidateConfigurationEdits(){CommandCenterState s=new CommandCenterState();NBTTagCompound n=new NBTTagCompound();n.setInteger("ReserveTier",2);s.configure("unit",n);long version=s.configRevision;s.notify("threat","incoming","",20);s.acknowledge("threat");assertEquals(version,s.configRevision);n.setInteger("Reserve",3);s.configure("unit",n);assertTrue(s.configRevision>version);}
    @Test public void configurationVersionSurvivesRestart(){CommandCenterState s=new CommandCenterState();s.roles.put(new UUID(1,1),CommandCenterState.Role.COMMANDER);NBTTagCompound n=new NBTTagCompound();n.setInteger("ReserveTier",2);s.configure("unit",n);s.notify("threat","incoming","",20);CommandCenterState copy=CommandCenterState.read(s.write());assertEquals(s.configRevision,copy.configRevision);assertEquals(s.revision,copy.revision);}
    @Test public void legacyConfigurationHasInitialVersion(){NBTTagCompound old=new NBTTagCompound();old.setLong("Revision",42);assertEquals(42,CommandCenterState.read(old).configRevision);}
    @Test public void failedBatteryCannotClaimAnotherBatterysKill(){DefenseBattleLog log=new DefenseBattleLog();UUID target=UUID.randomUUID(),a=UUID.randomUUID(),b=UUID.randomUUID();log.shot(a,"A","A",target,1);log.shot(b,"B","B",target,2);log.outcome(a,target,false,3);log.outcome(b,target,true,4);assertEquals(0,log.summary("A").getInteger("Intercepted"));assertEquals(1,log.summary("A").getInteger("Assisted"));assertEquals(1,log.summary("B").getInteger("Intercepted"));assertEquals(1,log.summary("").getInteger("Intercepted"));assertEquals(0,log.summary("A").getDouble("Rate"),.001);}
    @Test public void oneTargetHasOneWinningBattery(){DefenseBattleLog log=new DefenseBattleLog();UUID target=UUID.randomUUID(),a=UUID.randomUUID(),b=UUID.randomUUID();log.shot(a,"A","A",target,1);log.shot(b,"B","B",target,2);log.outcome(a,target,true,3);log.outcome(b,target,true,4);assertEquals(1,log.summary("A").getInteger("Intercepted"));assertEquals(0,log.summary("B").getInteger("Intercepted"));}
    @Test public void oldBattleWithoutWinnerUsesActualSuccessfulShot(){DefenseBattleLog log=new DefenseBattleLog();UUID target=UUID.randomUUID(),a=UUID.randomUUID(),b=UUID.randomUUID();log.shot(a,"A","A",target,1);log.shot(b,"B","B",target,2);log.outcome(a,target,false,3);log.outcome(b,target,true,4);log.targets.get(target).removeTag("WinningBattery");DefenseBattleLog saved=DefenseBattleLog.read(log.write());assertEquals(0,saved.summary("A").getInteger("Intercepted"));assertEquals(1,saved.summary("B").getInteger("Intercepted"));}
    @Test public void longTraceKeepsLaunchTurnAndEndingWithinBound(){NBTTagCompound n=new NBTTagCompound();for(int i=0;i<1000;i++)DefenseBattleLog.sample(n,i<500?i:500,80,i<500?0:i-500,i*20L);NBTTagList trace=n.getTagList("Trace",10);assertEquals(128,trace.tagCount());assertEquals(0,trace.getCompoundTagAt(0).getLong("Tick"));assertEquals(999*20L,trace.getCompoundTagAt(127).getLong("Tick"));boolean turn=false;for(int i=0;i<trace.tagCount();i++)if(trace.getCompoundTagAt(i).getLong("Tick")==500*20L)turn=true;assertTrue(turn);}
    @Test public void replayEventsDoNotDuplicateLargeTraces(){DefenseBattleLog log=new DefenseBattleLog();UUID target=UUID.randomUUID(),shot=UUID.randomUUID();log.track(target,1);log.shot(shot,"A","A",target,2);for(int i=0;i<200;i++){DefenseBattleLog.sample(log.targets.get(target),i,80,0,i*20+1);DefenseBattleLog.sample(log.shots.get(shot),i,80,10,i*20+2);}log.outcome(shot,target,true,5000);NBTTagCompound replay=log.replayEpisode(target);NBTTagList events=replay.getTagList("Events",10);for(int i=0;i<events.tagCount();i++)assertFalse(events.getCompoundTagAt(i).hasKey("Trace"));assertEquals(128,log.shots.get(shot).getTagList("Trace",10).tagCount());assertEquals(64,replay.getTagList("Flights",10).getCompoundTagAt(0).getTagList("Trace",10).tagCount());}
    @Test public void terminalObservationMapDoesNotTransmitEveryHistoricalPatch(){TeamIntelData intel=new TeamIntelData();UUID source=UUID.randomUUID();for(int i=0;i<20;i++)intel.contact("x","X","pvo",i*10,80,0,1,i*200,"EO",source);assertTrue(intel.contacts.get("x").getTagList("History",10).tagCount()>0);NBTTagCompound row=intel.viewport(0,0,256).getTagList("Contacts",10).getCompoundTagAt(0);assertFalse(row.hasKey("History"));assertEquals(190, row.getDouble("X"),.001);assertTrue(intel.contacts.get("x").hasKey("History"));}
}
